mapper.update:
UPDATE outbox_delivery SET status='DELIVERING',attempt_no=attempt_no+1,lease_owner=#{workerId},lease_until=#{leaseUntil},
  lease_generation=lease_generation+1,revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id='SOURCE_INDEX_FULLTEXT' AND created_by=#{userId}
  AND revision=#{leaseRevision} AND lease_generation=#{generation} AND attempt_no<3 AND next_attempt_at<=#{now}
  AND ((status='PENDING' AND lease_owner IS NULL AND lease_until IS NULL)
    OR (status='DELIVERING' AND lease_owner IS NOT NULL AND lease_until<=#{now}))

mapper.sql:
event_id=#{eventId} AND consumer_id='SOURCE_INDEX_FULLTEXT' AND created_by=#{userId} AND status='DELIVERING'
AND lease_owner=#{workerId} AND lease_generation=#{generation} AND revision=#{leaseRevision}
AND lease_until>#{now} AND lease_until>UTC_TIMESTAMP(6)

mapper.update:
UPDATE index_manifest SET verified_count=#{count},status='READY'
WHERE source_version=#{sourceVersion} AND parse_version=#{parseVersion} AND index_version=#{indexVersion}
  AND status='BUILDING' AND expected_count=#{count} AND verified_count=0 AND manifest_sha256=#{manifestSha256}
  AND mode='FULLTEXT' AND config_sha256=#{configSha256}

UPDATE source_index_build SET status=#{resultStatus},result_ref=#{resultRef},revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id='SOURCE_INDEX_FULLTEXT' AND index_version=#{indexVersion}
  AND created_by=#{userId} AND revision=#{buildRevision} AND status='BUILDING' AND manifest_sha256=#{manifestSha256}
  AND execution_deadline>#{now} AND execution_deadline>UTC_TIMESTAMP(6)
    AND

UPDATE outbox_delivery SET status='FAILED',lease_owner=NULL,lease_until=NULL,last_error='INDEX_LIMIT',revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id='SOURCE_INDEX_FULLTEXT' AND created_by=#{userId}
  AND revision=#{leaseRevision} AND lease_generation=#{generation}
  AND (status='PENDING' OR status='DELIVERING' AND lease_until<=#{now})

mapper.select:
SELECT i.chunk_id AS chunkId,i.point_id AS pointId,i.vector_sha256 AS vectorSha256,i.embedding_invocation_id AS invocationId,
  i.verified_at AS verifiedAt,i.status AS status,i.created_by AS createdBy,i.classification AS classification,
  c.ordinal AS ordinal FROM index_item i JOIN source_chunk c ON c.tenant_id=i.tenant_id AND c.source_version=i.source_version
  AND c.parse_version=i.parse_version AND c.chunk_id=i.chunk_id
WHERE i.source_version=#{sourceVersion} AND i.parse_version=#{parseVersion} AND i.index_version=#{indexVersion}
ORDER BY c.ordinal,c.chunk_id LIMIT #{fetchLimit}
